with lines as (select id, host, log_ts, level, status_code, key, value from app_logs lateral view outer explode(context) e as key, value) select date_trunc('hour', log_ts) as hour_window, size(collect_set(level)) as num_levels, round(sum(status_code) / nullif(count(case when key = 'version' then 1 end), 0), 2) as status_code_per_version, round(avg(status_code), 2) as avg_status_code, count(case when key = 'version' then 1 end) as version_count from lines group by date_trunc('hour', log_ts) having version_count < 1000 order by version_count desc nulls first;
